/* ————————————————————————————————————————————
   Program Tracker — "chalk & iron"
   Light, calm, data-first coach's logbook.
   Color is functional only: status + RPE scale.
   ———————————————————————————————————————————— */

:root {
  --bg: #f2f3f1;
  --surface: #ffffff;
  --ink: #14181c;
  --muted: #5c646c;
  --faint: #8b9299;
  --line: #dcded9;
  --line-strong: #b9bfc0;

  --good: #1e7a46;
  --good-bg: #e6f4ec;
  --warn: #96660a;
  --warn-bg: #fff3d6;
  --bad: #c92a2a;
  --bad-bg: #fdecec;

  --focus: #2b6cb0;

  --font-ui: "Barlow", system-ui, sans-serif;
  --font-cond: "Barlow Semi Condensed", "Barlow", system-ui, sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;

  --radius: 6px;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-ui);
  font-size: 15px;
  line-height: 1.45;
  -webkit-font-smoothing: antialiased;
}

h1,
h2,
h3 {
  font-family: var(--font-cond);
  font-weight: 700;
  letter-spacing: 0.005em;
  margin: 0;
}
h1 { font-size: 26px; line-height: 1.15; }
h2 { font-size: 19px; }
h3 { font-size: 16px; }

a { color: inherit; text-decoration: none; }

code,
.mono {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}

/* —— primitives ————————————————————————— */

.btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 1px solid var(--ink);
  background: var(--ink);
  color: #fff;
  font: 600 14px var(--font-ui);
  padding: 7px 14px;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background 120ms, transform 60ms;
}
.btn:hover { background: #2a3138; }
.btn:active { transform: translateY(1px); }
.btn:disabled { opacity: 0.45; cursor: default; }

.btn.ghost {
  background: transparent;
  color: var(--ink);
  border-color: var(--line-strong);
}
.btn.ghost:hover { background: #eceee9; }
.btn.danger { background: transparent; color: var(--bad); border-color: var(--bad); }
.btn.danger:hover { background: var(--bad-bg); }

.input,
.select,
.textarea {
  width: 100%;
  font: 500 14px var(--font-ui);
  color: var(--ink);
  background: var(--surface);
  border: 1px solid var(--line-strong);
  border-radius: var(--radius);
  padding: 7px 10px;
}
.input:focus,
.select:focus,
.textarea:focus {
  outline: 2px solid var(--focus);
  outline-offset: 0;
  border-color: var(--focus);
}
.label {
  display: block;
  font: 600 13px var(--font-ui);
  color: var(--muted);
  margin-bottom: 4px;
}

/* —— surfaces ————————————————————————— */

.panel {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 8px;
}
.panel-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 18px 10px;
  border-bottom: 1px solid var(--line);
}
.panel-body { padding: 16px 18px; }

/* —— tables ——————————————————————————— */

table.sheet {
  width: 100%;
  border-collapse: collapse;
}
table.sheet th {
  font: 600 13px var(--font-ui);
  color: var(--faint);
  text-align: left;
  padding: 8px 14px;
  border-bottom: 1px solid var(--line-strong);
  white-space: nowrap;
}
table.sheet td {
  padding: 9px 14px;
  border-bottom: 1px solid var(--line);
  vertical-align: middle;
}
table.sheet tr:last-child td { border-bottom: none; }
table.sheet tr.rowlink:hover td { background: #f7f8f5; cursor: pointer; }

/* —— status / data chips ————————————————— */

.pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font: 600 12px var(--font-ui);
  padding: 2px 9px;
  border-radius: 99px;
  white-space: nowrap;
}
.pill.good { color: var(--good); background: var(--good-bg); }
.pill.warn { color: var(--warn); background: var(--warn-bg); }
.pill.bad { color: var(--bad); background: var(--bad-bg); }
.pill.neutral { color: var(--muted); background: #eceee9; }

.num {
  font: 500 14px var(--font-mono);
  font-variant-numeric: tabular-nums;
}
.num.big {
  font-size: 22px;
  font-weight: 600;
}

/* RPE functional scale: 1–6 easy · 7–8 hard · 9–10 maximal */
.rpe { display: inline-flex; align-items: center; gap: 4px; font: 500 12px var(--font-mono); }
.rpe::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 99px;
  background: currentColor;
}
.rpe.low { color: var(--good); }
.rpe.mid { color: var(--warn); }
.rpe.high { color: var(--bad); }

/* —— set chips (program view) ———————————— */

.setchip {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  font: 500 13px var(--font-mono);
  background: #f4f5f2;
  border: 1px solid var(--line);
  border-radius: 5px;
  padding: 3px 8px;
}
.setchip .rep { font-weight: 600; }
.setchip .sub { color: var(--faint); font-size: 12px; }
.setchip.warm { background: transparent; border-style: dashed; color: var(--muted); }

/* —— misc ————————————————————————————— */

.page-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}
.sub { color: var(--muted); font-size: 14px; }
.subtle { color: var(--faint); font-size: 13px; }

.divider { border: none; border-top: 1px solid var(--line); margin: 14px 0; }

.skeleton {
  border-radius: var(--radius);
  background: linear-gradient(90deg, #e8eae6 25%, #eff1ec 50%, #e8eae6 75%);
  background-size: 200% 100%;
  animation: shimmer 1.2s infinite linear;
  min-height: 16px;
}
@keyframes shimmer {
  to { background-position: -200% 0; }
}

@media (prefers-reduced-motion: reduce) {
  .skeleton { animation: none; }
  .btn { transition: none; }
}

.empty {
  padding: 28px 18px;
  text-align: center;
  color: var(--muted);
  font-size: 14px;
}

